import sys
from abc import ABC, abstractmethod
import math

class Shape(ABC):
    @abstractmethod
    def calculateArea(self):
        pass

class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def calculateArea(self):
        return math.pi * self.radius ** 2

class Rectangle(Shape):
    def __init__(self, length, width):
        self.length = length
        self.width = width

    def calculateArea(self):
        return self.length * self.width

def main():
    lines = [line.strip() for line in sys.stdin.read().splitlines()]

    if not lines:
        return

    shape_type = lines[0].strip()

    # Handle case where radius is on same line as shape type (e.g., "circle5")
    if shape_type.startswith("circle"):
        # Extract radius from the same line or next line
        if len(shape_type) > 6:  # "circle" is 6 chars
            radius = float(shape_type[6:])
        else:
            radius = float(lines[1])
        circle = Circle(radius)
        area = circle.calculateArea()
        print("{:.2f}".format(area))
    elif shape_type == "rectangle":
        length = float(lines[1])
        width = float(lines[2])
        rectangle = Rectangle(length, width)
        area = rectangle.calculateArea()
        print("{:.2f}".format(area))

if __name__ == "__main__":
    main()
